import Foundation


// SVG_Captcha_Process.java
final class MailCaptchaProcessor: NSObject {

    private static let model = ""

    // 等價於 Java 的 public static String Solve_Captcha(String captcha_str)
    static func solveCaptcha(_ captchaStr: String) -> String {

        do {
            // === Base64 decode model ===
            guard
                let modelData = Data(base64Encoded: model),
                let decodedModel = String(data: modelData, encoding: .utf8),
                let jsonData = decodedModel.data(using: .utf8),
                let parsedModel = try JSONSerialization.jsonObject(with: jsonData) as? [String: String]
            else {
                return captchaStr
            }

            // === Parse SVG ===
            let parser = InternalSVGParser()
            let svgData = Data(captchaStr.utf8)
            let xmlParser = XMLParser(data: svgData)
            xmlParser.delegate = parser

            if !xmlParser.parse() {
                return captchaStr
            }

            // === Filter paths without stroke ===
            let noStrokePaths = parser.paths.filter { $0.stroke.isEmpty }

            // === Extract numeric values from d attribute ===
            var vals: [Int] = []

            for path in noStrokePaths {
                let d = path.d
                if !d.isEmpty {
                    let firstPart = d.components(separatedBy: ".").first ?? ""
                    let numericPart = firstPart.replacingOccurrences(of: "M", with: "")
                    if let value = Int(numericPart) {
                        vals.append(value)
                    }
                }
            }

            // === Sort values ===
            let sortedVals = vals.sorted()

            // === solution array (size = 6) ===
            var solution: [String?] = Array(repeating: nil, count: 6)

            // === Fill solution ===
            for i in 0..<noStrokePaths.count {
                let d = noStrokePaths[i].d

                let pattern = d.replacingOccurrences(
                    of: "[\\d.\\s]*",
                    with: "",
                    options: .regularExpression
                )

                if let value = parsedModel[pattern] {
                    let indexValue = vals[i]
                    if let index = sortedVals.firstIndex(of: indexValue),
                       index < solution.count {
                        solution[index] = value
                    }
                }
            }

            // === Build final result ===
            var finalSolution = ""
            for s in solution {
                if let s {
                    finalSolution.append(s)
                }
            }

            return finalSolution

        } catch {
            return captchaStr
        }
    }

    // ===== 以下是 SVG parser（等價於 Java DOM）=====
    private final class InternalSVGParser: NSObject, XMLParserDelegate {

        struct Path {
            let d: String
            let stroke: String
        }

        var paths: [Path] = []

        func parser(
            _ parser: XMLParser,
            didStartElement elementName: String,
            namespaceURI: String?,
            qualifiedName qName: String?,
            attributes attributeDict: [String : String]
        ) {
            if elementName == "path" {
                let d = attributeDict["d"] ?? ""
                let stroke = attributeDict["stroke"] ?? ""
                paths.append(Path(d: d, stroke: stroke))
            }
        }
    }
}
